-- ----------------------------
-- Table structure for t_limittime_exchange
-- ----------------------------
DROP TABLE IF EXISTS `t_limittime_exchange`;
CREATE TABLE `t_limittime_exchange`  (
  `id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `timeType` int(11) NULL DEFAULT NULL,
  `activeTime` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `openServerTime` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `weight` int(11) NULL DEFAULT NULL,
  `imgUrl` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `itemStr` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `open` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Compact;

-- ----------------------------
-- Table structure for t_luckwheel_config
-- ----------------------------
DROP TABLE IF EXISTS `t_luckwheel_config`;
CREATE TABLE `t_luckwheel_config`  (
  `id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `serverName` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `startTime` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `endTime` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `joinTimes` int(11) NULL DEFAULT NULL,
  `consumeStr` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `rewardStr` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `vipStr` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `open` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Compact;

